// AG Grid v33+ (checked against v36.2 docs). Community modules only.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AgGridReact } from "ag-grid-react";
import {
  AllCommunityModule,
  ModuleRegistry,
  type ColDef,
  type GetRowIdParams,
  type GridReadyEvent,
  type ValueFormatterParams,
} from "ag-grid-community";

// Register once, before any grid is created
ModuleRegistry.registerModules([AllCommunityModule]);

interface Quote {
  symbol: string;
  price: number;
  change: number;
}

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

// Value formatters must handle null/undefined values
const currencyFormatter = (p: ValueFormatterParams<Quote, number>) =>
  p.value == null ? "" : usd.format(p.value);

export function QuotesGrid() {
  const timer = useRef<ReturnType<typeof setInterval> | null>(null);

  const [rowData] = useState<Quote[]>([
    { symbol: "AAPL", price: 190.12, change: 0 },
    { symbol: "MSFT", price: 410.55, change: 0 },
    { symbol: "NVDA", price: 120.3, change: 0 },
  ]);
  const latest = useRef<Quote[]>(rowData);

  const columnDefs = useMemo<ColDef<Quote>[]>(
    () => [
      { field: "symbol" },
      { field: "price", valueFormatter: currencyFormatter, enableCellChangeFlash: true },
      { field: "change", enableCellChangeFlash: true },
    ],
    [],
  );

  // Stable row IDs let transactions match updates to existing rows by key
  const getRowId = useCallback((params: GetRowIdParams<Quote>) => params.data.symbol, []);

  // Hypothetical feed: replace with your WebSocket / message handler
  const onGridReady = useCallback((e: GridReadyEvent<Quote>) => {
    timer.current = setInterval(() => {
      const update = latest.current.map((r) => {
        const change = +(Math.random() * 2 - 1).toFixed(2);
        return { ...r, price: +(r.price + change).toFixed(2), change };
      });
      latest.current = update;
      // Batched: queued updates are applied together after asyncTransactionWaitMillis
      e.api.applyTransactionAsync({ update });
    }, 100);
  }, []);

  useEffect(() => () => { if (timer.current) clearInterval(timer.current); }, []);

  return (
    <div style={{ height: 400 }}>
      <AgGridReact<Quote>
        rowData={rowData}
        columnDefs={columnDefs}
        getRowId={getRowId}
        asyncTransactionWaitMillis={50}
        cellFlashDuration={500}
        onGridReady={onGridReady}
      />
    </div>
  );
}
